import java.util.*;
import java.io.*;

public class B {

    public static int readIntFromInput(BufferedReader br) throws IOException {
        return Integer.parseInt(br.readLine().trim());
    }

    public static String[] readStringArray(BufferedReader br) throws IOException {
        return br.readLine().trim().split(" ");
    }

    public static int[] readIntArray(BufferedReader br) throws IOException {
        String[] tokens = readStringArray(br);
        int[] array = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            array[i] = Integer.parseInt(tokens[i]);
        }
        return array;
    }

    public static char[] fillXWithChar(char[] array, int size, char ch) {
        char[] result = new char[size];
        for (int i = 0; i < size; i++) {
            result[i] = (array[i] == 'X') ? ch : array[i];
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int testCases = 1;
        StringBuilder outputBuilder = new StringBuilder();

        while (testCases-- > 0) {
            char[] lineChars = br.readLine().trim().toCharArray();
            int length = lineChars.length;

            if (length == 1) {
                if (lineChars[0] == '0' || lineChars[0] == '_' || lineChars[0] == 'X' || lineChars[0] == '1') {
                    outputBuilder.append("1\n");
                    continue;
                }
            }

            long totalCount = 0;
            boolean containsX = false;
            for (char c : lineChars) {
                if (c == 'X') {
                    containsX = true;
                    break;
                }
            }

            if (containsX) {
                for (char digit = '0'; digit <= '9'; digit++) {
                    totalCount += evaluatePattern(fillXWithChar(lineChars, length, digit), length);
                }
            } else {
                totalCount += evaluatePattern(lineChars, length);
            }
            outputBuilder.append(totalCount).append("\n");
        }
        System.out.print(outputBuilder);
    }

    public static long evaluatePattern(char[] str, int n) {
        if (n == 1 || str[0] == '0') return 0;
        long totalWays = 0;
        int underscoreCount = 0;
        for (int i = 1; i < n - 2; i++) {
            if (str[i] == '_') underscoreCount++;
        }
        totalWays += checkForPattern(str, "25", n, underscoreCount);
        totalWays += checkForPattern(str, "50", n, underscoreCount);
        totalWays += checkForPattern(str, "75", n, underscoreCount);

        if (n > 2 && (str[0] == '_' || str[0] == '0')) {
            totalWays *= 9;
        }

        if (n >= 3) {
            if ((str[n - 1] == '_' || str[n - 1] == '0') && (str[n - 2] == '_' || str[n - 2] == '0')) {
                long tempVal = (long) Math.pow(10, underscoreCount);
                if (str[0] == '_') tempVal *= 9;
                totalWays += tempVal;
            }
        }
        return totalWays;
    }

    public static long checkForPattern(char[] str, String suffix, int n, int un) {
        if (n < 2) return 0;
        char lastChar = suffix.charAt(1);
        char firstChar = suffix.charAt(0);
        if (str[n - 1] == '_' || str[n - 1] == lastChar) {
            if (str[n - 2] == '_' || str[n - 2] == firstChar) {
                return (long) Math.pow(10, un);
            }
        }
        return 0;
    }
}
